-			    MTK_DPI_POLARITY_FALLING : MTK_DPI_POLARITY_RISING;
-	dpi_pol->vsync_pol = vm->flags & DISPLAY_FLAGS_VSYNC_HIGH ?
-			    MTK_DPI_POLARITY_FALLING : MTK_DPI_POLARITY_RISING;
-
-	/*
-	 * Depending on the IP version, we may output a different amount of
