+static inline void mtk_dpi_mask(struct mtk_dpi *dpi, u32 offset, u32 val, u32 mask)
+{
+	u32 tmp = readl(dpi->regs + offset);
+
+	tmp &= ~mask;
+	tmp |= (val & mask);
+	writel(tmp, dpi->regs + offset);
+}
